import pyomo.environ as pyo

DATA = {
    "foods": ["Eggs", "Grains", "Berries", "Nuts",
              "Salmon", "Vegetables", "Rice", "Meat"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per serving
    "cost": {
        "Eggs": 4, "Grains": 3, "Berries": 2, "Nuts": 4,
        "Salmon": 9, "Vegetables": 3, "Rice": 6, "Meat": 6,
    },
    # nutrient content per serving
    "protein": {
        "Eggs": 2, "Grains": 7, "Berries": 6, "Nuts": 16,
        "Salmon": 20, "Vegetables": 6, "Rice": 6, "Meat": 5,
    },
    "carbs": {
        "Eggs": 4, "Grains": 9, "Berries": 18, "Nuts": 3,
        "Salmon": 11, "Vegetables": 27, "Rice": 30, "Meat": 1,
    },
    "calories": {
        "Eggs": 282, "Grains": 104, "Berries": 71, "Nuts": 116,
        "Salmon": 175, "Vegetables": 132, "Rice": 251, "Meat": 74,
    },
    # minimum daily requirements
    "req": {
        "protein": 84,
        "carbs": 195,
        "calories": 1941,
    },
    # map nutrient name -> content dict
    "content": {
        "protein": "protein",
        "carbs": "carbs",
        "calories": "calories",
    },
}


def build_model(data=None):
    d = data or DATA
    m = pyo.ConcreteModel()

    m.I = pyo.Set(initialize=d["foods"])
    m.N = pyo.Set(initialize=d["nutrients"])

    # x[i]: number of servings of food i (>= 0)
    m.x = pyo.Var(m.I, within=pyo.NonNegativeReals)

    # Objective: minimise total cost
    m.obj = pyo.Objective(
        expr=sum(d["cost"][i] * m.x[i] for i in m.I),
        sense=pyo.minimize,
    )

    # Nutrient requirement constraints (>= each minimum)
    def nutrient_rule(m, n):
        return sum(d[d["content"][n]][i] * m.x[i] for i in m.I) >= d["req"][n]

    m.nutrient_req = pyo.Constraint(m.N, rule=nutrient_rule)

    return m


